exercises.solution:
import java.util.*;

public class Medicine {
    private final String name;
    private final int mg;

    public Medicine(String name, int mg) {
        this.name = name;
        this.mg = mg;
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof Medicine)) return false;
        Medicine m = (Medicine) o;
        return name.equalsIgnoreCase(m.name) && mg == m.mg;
    }

    @Override
    public int hashCode() {
        // equals ignores capitals, so the hash must ignore them too
        return Objects.hash(name.toLowerCase(), mg);
    }

    @Override
    public String toString() { return name + " " + mg + "mg"; }

    public static int distinct(List<Medicine> meds) {
        return new HashSet<>(meds).size();
    }

    public static Map<Medicine, Integer> tally(List<Medicine> meds) {
        Map<Medicine, Integer> counts = new HashMap<>();
        for (Medicine m : meds) counts.put(m, counts.getOrDefault(m, 0) + 1);
        return counts;
    }
}
